import { useEffect, useRef } from 'react';
import * as THREE from 'three';

const badges = ['Engineering Leadership', 'Team Building', 'Technical Strategy', 'Delivery Excellence', 'Cloud & Scale', 'AI / LLM'];

const stats = [
    { value: '14+', label: 'yrs exp' },
    { value: '18', label: 'engineers grown' },
    { value: '50M+', label: 'events/day' },
    { value: '$4M+', label: 'budget owned' },
];

export default function Home({ theme }) {
    const canvasRef = useRef(null);

    useEffect(() => {
        const cleanup = initParticles(canvasRef.current, theme);
        return cleanup;
    }, [theme]);

    return (
        <div id="home">
            <canvas ref={canvasRef} id="homeCanvas" />
            <div className="home-content">
                <div className="home-hero">
                    <p className="home-eyebrow">Engineering Manager</p>
                    <h1 className="home-title">polyglot.dev</h1>
                    <p className="home-tagline">
                        Leading engineering teams to deliver AI-powered distributed systems at scale.
                        From building high-performing squads to architecting platforms serving 50M+ events/day.
                    </p>
                    <div className="home-stats">
                        {stats.map((s, i) => (
                            <div className="home-stat" key={s.label}>
                                <span className="home-stat-value">{s.value}</span>
                                <span className="home-stat-label">{s.label}</span>
                            </div>
                        ))}
                    </div>
                    <div className="home-badges">
                        {badges.map(b => (
                            <span className="home-badge" key={b}>{b}</span>
                        ))}
                    </div>
                    <div className="home-building">
                        <span className="home-building-dot" />
                        <span className="home-building-text">
                            Growing engineering teams that ship reliable, impactful systems
                        </span>
                    </div>
                    <div className="home-links">
                        <a
                            href="https://github.com/poliglots"
                            target="_blank"
                            rel="noreferrer"
                            className="home-cta home-cta-primary"
                        >
                            GitHub
                        </a>
                    </div>
                </div>
            </div>
        </div>
    );
}

const particleColor = { dark: 0x7ec5a6, light: 0x0060df };

function initParticles(canvas, theme) {
    const w = window.innerWidth;
    const h = window.innerHeight * 0.95;

    const renderer = new THREE.WebGLRenderer({ canvas, antialias: true, alpha: true });
    renderer.setSize(w, h);
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));

    const scene = new THREE.Scene();
    const camera = new THREE.PerspectiveCamera(60, w / h, 0.1, 2000);
    camera.position.z = 320;

    const count = 2500;
    const positions = new Float32Array(count * 3);
    const speeds = new Float32Array(count);
    for (let i = 0; i < count; i++) {
        positions[i * 3]     = (Math.random() - 0.5) * 1200;
        positions[i * 3 + 1] = (Math.random() - 0.5) * 1200;
        positions[i * 3 + 2] = (Math.random() - 0.5) * 800;
        speeds[i] = 0.2 + Math.random() * 0.6;
    }

    const geometry = new THREE.BufferGeometry();
    geometry.setAttribute('position', new THREE.Float32BufferAttribute(positions, 3));

    const material = new THREE.PointsMaterial({
        color: particleColor[theme] ?? particleColor.dark,
        size: 1.8,
        transparent: true,
        opacity: theme === 'dark' ? 0.55 : 0.4,
        sizeAttenuation: true,
    });

    const points = new THREE.Points(geometry, material);
    scene.add(points);

    let animId;
    let frame = 0;
    function animate() {
        animId = requestAnimationFrame(animate);
        frame++;
        points.rotation.y += 0.0008;
        points.rotation.x += 0.0003;

        const pos = geometry.attributes.position;
        for (let i = 0; i < count; i++) {
            pos.setY(i, positions[i * 3 + 1] + Math.sin(frame * 0.005 + speeds[i] * 10) * 0.3);
        }
        pos.needsUpdate = true;

        renderer.render(scene, camera);
    }
    animate();

    function handleResize() {
        const nw = window.innerWidth;
        const nh = window.innerHeight * 0.95;
        camera.aspect = nw / nh;
        camera.updateProjectionMatrix();
        renderer.setSize(nw, nh);
    }
    window.addEventListener('resize', handleResize);

    return () => {
        cancelAnimationFrame(animId);
        window.removeEventListener('resize', handleResize);
        geometry.dispose();
        material.dispose();
        renderer.dispose();
    };
}
